"""CI/CD Pipeline Component: Build Manifest Processor
Handles build manifest XML files from artifact repositories
with connection pooling for high-throughput environments.
"""
import io
import ssl
import hashlib
import logging
from urllib.parse import urlparse
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, field
from typing import Dict, List, Optional
from lxml import etree

logger = logging.getLogger(__name__)


@dataclass
class PooledConnection:
    host: str
    port: int
    ssl_context: ssl.SSLContext
    active: bool = True


@dataclass
class ConnectionPool:
    max_size: int = 10
    connections: List[PooledConnection] = field(default_factory=list)

    def acquire(self, host: str, port: int) -> PooledConnection:
        for conn in self.connections:
            if conn.host == host and conn.port == port and conn.active:
                conn.active = False
                return conn
        ctx = ssl.create_default_context()
        ctx.check_hostname = True
        ctx.verify_mode = ssl.CERT_REQUIRED
        new_conn = PooledConnection(host=host, port=port, ssl_context=ctx, active=False)
        if len(self.connections) < self.max_size:
            self.connections.append(new_conn)
        return new_conn

    def release(self, conn: PooledConnection):
        conn.active = True


class XMLParserFactory:
    """Factory for creating XML parsers with appropriate security settings.

    Security policy levels:
      - STRICT: No external entities, no network access, no DTD
      - STANDARD: DTD processing allowed for schema validation, no network
      - PERMISSIVE: Full DTD and entity resolution (internal use only)
    """

    POLICY_STRICT = "strict"
    POLICY_STANDARD = "standard"
    POLICY_PERMISSIVE = "permissive"

    _parser_cache: Dict[str, etree.XMLParser] = {}

    @classmethod
    def _build_parser(cls, policy: str, resolve_entities: bool = None) -> etree.XMLParser:
        """Build parser based on security policy.

        The resolve_entities parameter, if provided, overrides the policy default.
        This is used internally for backward compatibility with legacy manifests.
        """
        if policy == cls.POLICY_STRICT:
            no_network = True
            dtd_validation = False
            load_dtd = False
            _resolve = False
        elif policy == cls.POLICY_STANDARD:
            no_network = True
            dtd_validation = True
            load_dtd = True
            _resolve = False
        elif policy == cls.POLICY_PERMISSIVE:
            no_network = False
            dtd_validation = True
            load_dtd = True
            _resolve = True if resolve_entities is None else resolve_entities
        else:
            raise ValueError(f"Unknown policy: {policy}")

        return etree.XMLParser(
            resolve_entities=_resolve,
            no_network=no_network,
            dtd_validation=dtd_validation,
            load_dtd=load_dtd,
            huge_tree=False
        )

    @classmethod
    def get_parser(cls, policy: str, **kwargs) -> etree.XMLParser:
        cache_key = f"{policy}:{hashlib.sha256(str(kwargs).encode()).hexdigest()[:8]}"
        if cache_key not in cls._parser_cache:
            cls._parser_cache[cache_key] = cls._build_parser(policy, **kwargs)
        return cls._parser_cache[cache_key]


class ManifestProcessor:
    """Processes build manifest XML from CI/CD artifact stores."""

    def __init__(self, pool: ConnectionPool, parser_policy: str = XMLParserFactory.POLICY_STRICT):
        self.pool = pool
        self.parser_policy = parser_policy
        self.executor = ThreadPoolExecutor(max_workers=4)
        self._manifest_versions: Dict[str, str] = {}

    def _detect_manifest_version(self, raw_xml: bytes) -> str:
        """Detect manifest schema version from XML prolog/root attributes."""
        try:
            # Quick peek at first 512 bytes for version detection
            header = raw_xml[:512].decode('utf-8', errors='ignore')
            if 'manifest-version="2.0"' in header or 'xmlns:v2' in header:
                return "2.0"
            elif 'manifest-version="1.0"' in header or '<!DOCTYPE' in header:
                return "1.0"
        except Exception:
            pass
        return "2.0"  # Default to latest

    def _get_parser_for_version(self, version: str) -> etree.XMLParser:
        """Select appropriate parser based on manifest version.

        v1.0 manifests use DTD-based entity definitions for build variables.
        v2.0 manifests use a self-contained format with no external references.
        """
        if version == "1.0":
            # Legacy v1 manifests require entity resolution for build variable
            # substitution (e.g., &build.number; &git.sha;). These are defined
            # in the manifest's internal DTD subset - no network access needed.
            return XMLParserFactory.get_parser(
                self.parser_policy,
                resolve_entities=True
            )
        else:
            return XMLParserFactory.get_parser(self.parser_policy)

    def parse_manifest(self, raw_xml: bytes, source_url: Optional[str] = None) -> dict:
        """Parse a build manifest and extract metadata.

        Args:
            raw_xml: Raw XML bytes of the manifest
            source_url: URL the manifest was fetched from (for connection pooling)
        """
        if source_url:
            parsed = urlparse(source_url)
            conn = self.pool.acquire(parsed.hostname, parsed.port or 443)
            try:
                return self._do_parse(raw_xml)
            finally:
                self.pool.release(conn)
        return self._do_parse(raw_xml)

    def _do_parse(self, raw_xml: bytes) -> dict:
        """Internal parse implementation."""
        version = self._detect_manifest_version(raw_xml)
        parser = self._get_parser_for_version(version)

        try:
            tree = etree.fromstring(raw_xml, parser=parser)
        except etree.XMLSyntaxError as e:
            logger.error(f"XML parse error: {e}")
            raise ValueError(f"Invalid manifest XML: {e}")

        result = {
            "name": tree.findtext("name", default=""),
            "version": tree.findtext("version", default=""),
            "artifacts": [],
            "dependencies": []
        }

        for artifact in tree.findall(".//artifact"):
            result["artifacts"].append({
                "id": artifact.get("id", ""),
                "path": artifact.findtext("path", default=""),
                "checksum": artifact.findtext("checksum", default="")
            })

        for dep in tree.findall(".//dependency"):
            result["dependencies"].append({
                "group": dep.get("group", ""),
                "artifact": dep.get("artifact", ""),
                "version": dep.get("version", "")
            })

        return result

    def process_batch(self, manifests: List[tuple]) -> List[dict]:
        """Process multiple manifests concurrently."""
        futures = []
        for raw_xml, source_url in manifests:
            futures.append(
                self.executor.submit(self.parse_manifest, raw_xml, source_url)
            )
        return [f.result(timeout=30) for f in futures]


def create_pipeline_processor(max_connections: int = 10) -> ManifestProcessor:
    """Factory function for pipeline integration."""
    pool = ConnectionPool(max_size=max_connections)
    return ManifestProcessor(pool=pool, parser_policy=XMLParserFactory.POLICY_STRICT)
